function validate([board]) {
  if (board.length < 1 || board.length > 25) return 'board has 1 to 25 rows.';
  const n = board[0].length;
  if (n < 1 || n > 25) return 'board has 1 to 25 columns.';
  if (board.some(row => row.length !== n)) return 'Every row needs the same length.';
  if (board.some(row => row.some(v => v !== 0 && v !== 1))) return 'Each cell is 0 or 1.';
  return null;
}

